#!/usr/bin/env python3
"""Independent, deliberately naive reference implementation of the contract."""
import sys, json, re
from fractions import Fraction

def ok_int(v, lo, hi):
    return isinstance(v, int) and not isinstance(v, bool) and lo <= v <= hi

def chk(c):
    if not c:
        raise ValueError

def ref(doc):
    chk(isinstance(doc, dict))
    chk(set(doc) == {"version","config","model","connections","packets"})
    chk(ok_int(doc["version"],1,1))
    cfg = doc["config"]; mdl = doc["model"]
    chk(isinstance(cfg, dict) and set(cfg)=={"slots","window","idle_timeout","len_quantum","gap_quantum","rate_num","rate_den","bucket_capacity","initial_tokens","pending_capacity","lanes","service","fallback","time_edges","count_edges","probability"})
    chk(isinstance(mdl, dict) and set(mdl)=={"classes","embedding_dim","length_embedding","gap_embedding","kernel","conv_weights","conv_bias","conv_shift","dense_weights","dense_bias"})
    C = mdl["classes"]; chk(ok_int(C,2,8))
    E = mdl["embedding_dim"]; chk(ok_int(E,1,4))
    S = cfg["slots"]; chk(ok_int(S,1,256))
    W = cfg["window"]; chk(ok_int(W,1,16))
    idle = cfg["idle_timeout"]; chk(ok_int(idle,1,10**12))
    lq = cfg["len_quantum"]; chk(ok_int(lq,1,65535))
    gq = cfg["gap_quantum"]; chk(ok_int(gq,1,65535))
    rn = cfg["rate_num"]; chk(ok_int(rn,1,10**6))
    rd = cfg["rate_den"]; chk(ok_int(rd,1,10**6))
    bc = cfg["bucket_capacity"]; chk(ok_int(bc,1,512))
    it = cfg["initial_tokens"]; chk(ok_int(it,0,bc))
    pcap = cfg["pending_capacity"]; chk(ok_int(pcap,1,512))
    L = cfg["lanes"]; chk(ok_int(L,1,4))
    svc = cfg["service"]; chk(isinstance(svc,list) and len(svc)==C and all(ok_int(x,1,10**6) for x in svc))
    fb = cfg["fallback"]; chk(ok_int(fb,0,C-1))
    te = cfg["time_edges"]; chk(isinstance(te,list) and 1<=len(te)<=16)
    chk(all(ok_int(x,0,10**12) for x in te) and te[0]==0 and all(te[i]<te[i+1] for i in range(len(te)-1)))
    ce = cfg["count_edges"]; chk(isinstance(ce,list) and 1<=len(ce)<=16)
    chk(all(ok_int(x,0,20000) for x in ce) and ce[0]==0 and all(ce[i]<ce[i+1] for i in range(len(ce)-1)))
    pr = cfg["probability"]; chk(isinstance(pr,len(te)*[0]) and len(pr)==len(te))
    for r in pr: chk(isinstance(r,list) and len(r)==len(ce) and all(ok_int(x,0,65536) for x in r))
    LE = mdl["length_embedding"]; chk(isinstance(LE,list) and len(LE)==16)
    for r in LE: chk(isinstance(r,list) and len(r)==E and all(ok_int(x,-128,127) for x in r))
    GE = mdl["gap_embedding"]; chk(isinstance(GE,list) and len(GE)==16)
    for r in GE: chk(isinstance(r,list) and len(r)==E and all(ok_int(x,-128,127) for x in r))
    K = mdl["kernel"]; chk(ok_int(K,1,5) and K<=W)
    cw = mdl["conv_weights"]; chk(isinstance(cw,list) and 1<=len(cw)<=8)
    for frow in cw:
        chk(isinstance(frow,list) and len(frow)==K)
        for krow in frow:
            chk(isinstance(krow,list) and len(krow)==2*E and all(ok_int(x,-128,127) for x in krow))
    cb = mdl["conv_bias"]; chk(isinstance(cb,list) and len(cb)==len(cw) and all(ok_int(x,-2**31,2**31-1) for x in cb))
    cs = mdl["conv_shift"]; chk(isinstance(cs,list) and len(cs)==len(cw) and all(ok_int(x,0,16) for x in cs))
    dw = mdl["dense_weights"]; chk(isinstance(dw,list) and len(dw)==C)
    for r in dw: chk(isinstance(r,list) and len(r)==len(cw) and all(ok_int(x,-128,127) for x in r))
    db = mdl["dense_bias"]; chk(isinstance(db,list) and len(db)==C and all(ok_int(x,-2**31,2**31-1) for x in db))
    F = len(cw)
    conns = doc["connections"]; chk(isinstance(conns,list) and len(conns)<=2048)
    ids=[]; slot={}; label={}; split={}
    for c in conns:
        chk(isinstance(c,dict) and set(c)=={"id","slot","label","split"})
        i=c["id"]; chk(isinstance(i,str) and re.fullmatch(r"[A-Za-z0-9_-]{1,32}",i))
        chk(i not in slot)
        ids.append(i); slot[i]=c["slot"]; label[i]=c["label"]; split[i]=c["split"]
        chk(ok_int(c["slot"],0,S-1)); chk(ok_int(c["label"],0,C-1)); chk(c["split"] in ("dev","eval"))
    pkts = doc["packets"]; chk(isinstance(pkts,list) and len(pkts)<=20000)
    last=-1
    for p in pkts:
        chk(isinstance(p,dict) and set(p)=={"time","connection","length","draw"})
        chk(ok_int(p["time"],0,10**12)); chk(p["time"]>=last); last=p["time"]
        chk(p["connection"] in slot)
        chk(ok_int(p["length"],0,65535)); chk(ok_int(p["draw"],0,65535))

    # state
    gen = {s:0 for s in range(S)}
    occ = {s:None for s in range(S)}
    wins = {s:[] for s in range(S)}
    cls = {s:None for s in range(S)}
    lastap = {s:-1 for s in range(S)}
    anchor = {s:0 for s in s_key(S)}
    backlog = {s:0 for s in range(S)}
    lastpt = {s:0 for s in range(S)}
    avail = [0]*L
    pend = {}   # id -> job
    credit = it*rd
    lastref = 0
    nextid = 0
    votes = {i:[0]*C for i in range(len(ids))}
    cnt = {i:0 for i in range(len(ids))}
    opk=[]; oj=[]

    def requant(z, sh):
        if sh == 0: return z
        # round half away from zero
        if z >= 0:
            q = (2*z + (1<<sh)) // (2<<sh)
        else:
            q = -((-2*z + (1<<sh)) // (2<<sh))
        return q
    def cnn(window):
        x = []
        for (a,b) in window:
            x.append(LE[a] + GE[b])
        pooled=[]
        for f in range(F):
            vals=[]
            for j in range(0, W-K+1):
                z = cb[f]
                for k in range(K):
                    for d in range(2*E):
                        z += cw[f][k][d]*x[j+k][d]
                q = requant(z, cs[f])
                q = max(0, min(127, q))
                vals.append(q)
            pooled.append(max(vals))
        logits=[db[c] + sum(dw[c][f]*pooled[f] for f in range(F)) for c in range(C)]
        mx = max(logits)
        return logits, logits.index(mx)

    def finish_jobs(t):
        nonlocal pend
        ready = sorted([j for j in pend if pend[j]["done"] <= t], key=lambda j:(pend[j]["done"], j))
        for j in ready:
            job = pend.pop(j)
            s = job["slot"]
            if occ[s] is None or occ[s] != job["connection"] or gen[s] != job["generation"]:
                job["status"]="stale"
            elif j <= lastap[s]:
                job["status"]="superseded"
            else:
                job["status"]="applied"
                cls[s]=job["prediction"]; lastap[s]=j
            oj.append(job)

    for i,p in enumerate(pkts):
        t=p["time"]; cid=p["connection"]; ln=p["length"]; draw=p["draw"]
        finish_jobs(t)
        credit = min(bc*rd, credit + (t-lastref)*rn); lastref = t
        s = slot[cid]
        if occ[s] is None or occ[s] != cid or t - lastpt[s] >= idle:
            gen[s]+=1; occ[s]=cid; wins[s]=[]; cls[s]=None; lastap[s]=-1; anchor[s]=t; backlog[s]=0; gap=0
        else:
            gap = t - lastpt[s]
        lastpt[s]=t
        wins[s].append([min(15,ln//lq), min(15,gap//gq)])
        wins[s] = wins[s][-W:]
        backlog[s]+=1
        fwd = cls[s] if cls[s] is not None else fb
        votes[cid][fwd]+=1
        cnt[cid]+=1
        if len(wins[s]) < W:
            dec="warmup"; jid=None
        else:
            Ti = t - anchor[s]; Ci = backlog[s]
            ti = max([k for k,e in enumerate(te) if e<=Ti]); ci_ = max([k for k,e in enumerate(ce) if e<=Ci])
            pv = pr[ti][ci_]
            if draw >= pv: dec="probability"; jid=None
            elif credit < rd: dec="tokens"; jid=None
            elif len(pend) >= pcap: dec="queue"; jid=None
            else:
                dec="sent"; credit -= rd
                logits, pred = cnn([r[:] for r in wins[s]])
                jid = nextid; nextid+=1
                li = min(range(L), key=lambda k:(avail[k],k))
                st = max(t, avail[li]); dn = st + svc[pred]
                avail[li]=dn
                job = {"id":jid,"packet":i,"connection":cid,"slot":s,"generation":gen[s],"lane":li,"start":st,"done":dn,"window":[r[:] for r in wins[s]],"logits":logits,"prediction":pred}
                pend[jid]=job
                anchor[s]=t; backlog[s]=0
        opk.append({"index":i,"connection":cid,"generation":gen[s],"forward":fwd,"decision":dec,"credit":credit,"job":jid})
    finish_jobs(float('inf'))

    cout=[]
    preds={}
    for i,cid in enumerate(ids):
        if cnt[cid]==0: prd=None
        else:
            m=max(votes[cid]); prd=votes[cid].index(m)
        preds[cid]=prd
        cout.append({"id":cid,"split":split[cid],"label":label[cid],"packets":cnt[cid],"votes":votes[cid],"prediction":prd})
    conf={"dev":[[0]*C for _ in range(C)],"eval":[[0]*C for _ in range(C)]}
    obs={"dev":0,"eval":0}
    for cid in ids:
        if cnt[cid]==0: continue
        obs[split[cid]]+=1
        conf[split[cid]][label[cid]][preds[cid]]+=1
    rep={}
    for sp in ("dev","eval"):
        cf=conf[sp]
        fs=[]
        for c in range(C):
            tp=cf[c][c]; fp=sum(cf[r][c] for r in range(C))-tp; fn=sum(cf[c])-tp
            d=2*tp+fp+fn
            fs.append(Fraction(2*tp,d) if d else Fraction(0))
        mf=sum(fs)/C
        rep[sp]={"connections":obs[sp],"confusion":cf,"macro_f1":[mf.numerator,mf.denominator]}
    return {"packets":opk,"jobs":oj,"connections":cout,"reports":rep}

def s_key(S):
    return list(range(S))

if __name__ == "__main__":
    data = sys.stdin.buffer.read()
    try:
        from json import loads
        # strict parse with dup detection
        def hook(pairs):
            d={}
            for k,v in pairs:
                if k in d: raise ValueError
                d[k]=v
            return d
        doc = loads(data.decode('utf-8'), object_pairs_hook=hook, parse_constant=lambda n:(_ for _ in ()).throw(ValueError()))
        res = ref(doc)
        sys.stdout.write(json.dumps(res, separators=(",",":")))
    except Exception:
        sys.stdout.write('{"error":"invalid-input"}')
